i. CREATE TABLE Product (
   PCode VARCHAR(5) PRIMARY KEY,
   PName VARCHAR(50) NOT NULL,
   UPrice DECIMAL(10,2),
   Manufacturer VARCHAR(50)
);

ii. Primary Key: PCode (each product has a unique code)

iii. SELECT PCode, PName, UPrice FROM Product ORDER BY PName DESC, UPrice ASC;

iv. ALTER TABLE Product ADD Discount DECIMAL(10,2);

v. UPDATE Product SET Discount = CASE WHEN UPrice > 100 THEN UPrice * 0.10 ELSE 0 END;

vi. UPDATE Product SET UPrice = UPrice * 1.12 WHERE Manufacturer = 'Dove';

vii. SELECT Manufacturer, COUNT(*) AS ProductCount FROM Product GROUP BY Manufacturer;

