solution:
a) CREATE DATABASE Streams_Of_Students;

b) CREATE TABLE Student (
   AdmNo INT PRIMARY KEY,
   Name VARCHAR(50) NOT NULL,
   StCode VARCHAR(5),
   FOREIGN KEY (StCode) REFERENCES Stream(StCode)
);

c) Primary key of Student: AdmNo
   Primary key of Stream: StCode
   Foreign key in Student: StCode references Stream(StCode)

d) UPDATE Student SET StCode = 'S03' WHERE Name = 'Jay';

e) SELECT Name FROM Student WHERE Name LIKE '%a' ORDER BY Name ASC;

f) SELECT S.Name FROM Student S, Stream T WHERE S.StCode = T.StCode
   AND T.Stream IN ('Science', 'Humanities') ORDER BY S.Name ASC, S.AdmNo ASC;

g) SELECT StCode, COUNT(*) AS Cnt FROM Student GROUP BY StCode HAVING COUNT(*) > 1;

h) SELECT S.Name, T.Stream FROM Student S, Stream T WHERE S.StCode = T.StCode
   ORDER BY S.AdmNo DESC;
